BEGIN TRANSACTION;
CREATE TABLE commands(id TEXT PRIMARY KEY,request_hash TEXT NOT NULL,result TEXT NOT NULL);
CREATE TABLE events(id INTEGER PRIMARY KEY,event_version INTEGER NOT NULL,ts TEXT NOT NULL,subject TEXT NOT NULL,verb TEXT NOT NULL,actor TEXT NOT NULL,entity_id TEXT NOT NULL,command_id TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),idempotency_key TEXT NOT NULL UNIQUE);
CREATE TABLE projection_state(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE workspace_snapshot_payloads(snapshot_id TEXT PRIMARY KEY,body BLOB NOT NULL);
CREATE TABLE workspace_snapshots(id TEXT PRIMARY KEY,target TEXT NOT NULL,event_id INTEGER NOT NULL UNIQUE,payload_digest TEXT NOT NULL,payload_bytes INTEGER NOT NULL,pruned INTEGER NOT NULL DEFAULT 0,metadata TEXT NOT NULL CHECK(json_valid(metadata)));
CREATE INDEX workspace_snapshots_target_event ON workspace_snapshots(target,event_id DESC);
CREATE INDEX workspace_snapshots_retained ON workspace_snapshots(target,event_id DESC) WHERE pruned=0;
CREATE INDEX workspace_snapshots_retained_bytes ON workspace_snapshots(payload_bytes) WHERE pruned=0;
CREATE INDEX events_subject_entity ON events(subject,entity_id,id);
COMMIT;
PRAGMA user_version=16;
